INSERT OR IGNORE INTO wb_curricula (id, program_id, code, title_vi, version, review_status, academic_approval_note) VALUES ('cur_zh_log', 'prg_zh_log', 'CUR-ZH-LOG-2026', 'Giáo trình Khóa học Tiếng Trung Chuyên ngành Logistics & Chuỗi cung ứng', '1.0.0', 'published', 'Khóa chuyên ngành chuẩn V3.1.');
INSERT OR IGNORE INTO wb_courses (id, program_id, curriculum_id, slug, title_vi, language_code, summary_vi, total_weeks, sessions_per_week, review_status) VALUES ('crs_zh_log', 'prg_zh_log', 'cur_zh_log', 'chinese-specialized-logistics-course', 'Khóa học Tiếng Trung Chuyên ngành Logistics & Chuỗi cung ứng', 'zh', 'Khóa học chuyên ngành gắn thuật ngữ, chứng từ thực tế, hội thoại công việc và viết báo cáo chuyên môn.', 8, 3, 'published');
